export function mxServerUrl(input,location={protocol:'http:'}){let u;try{u=new URL(String(input).trim());}catch{throw Error('Bitte eine WebSocket-Adresse eintragen, z. B. ws://127.0.0.1:8787/ws');}if(!['ws:','wss:'].includes(u.protocol)||u.username||u.password||u.hash)throw Error('Nur ws:// oder wss:// ohne Zugangsdaten verwenden.');if(location.protocol==='https:'&&u.protocol==='ws:'&&!['127.0.0.1','localhost','[::1]'].includes(u.hostname))throw Error('Für einen HTTPS-/APK-Client braucht der Server wss://. Den lokalen WLAN-Test im Browser über http://PC-IP:8787 öffnen.');if(u.pathname==='/')u.pathname='/ws';return u.href;}
