  function bike(x,y,a,color,front,crashed){ctx.save();ctx.translate(x,y);ctx.rotate(-a);const s=front?1:.88;ctx.scale(s,s);ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#263c3b';ctx.lineWidth=4;for(const wx of [-18,20]){ctx.fillStyle='#20332f';ctx.beginPath();ctx.arc(wx,0,11,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#b7c8b7';ctx.lineWidth=2;ctx.beginPath();ctx.arc(wx,0,8,0,Math.PI*2);ctx.stroke();for(let n=0;n<6;n++){const angle=n*Math.PI/3+performance.now()*.008;ctx.beginPath();ctx.moveTo(wx,0);ctx.lineTo(wx+Math.cos(angle)*7,Math.sin(angle)*7);ctx.stroke();}}ctx.strokeStyle='#244039';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-18,0);ctx.lineTo(-6,-20);ctx.lineTo(12,-17);ctx.lineTo(20,0);ctx.lineTo(-18,0);ctx.stroke();ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(-9,-29,25,12,5);ctx.fill();ctx.fillStyle='#876143';ctx.fillRect(-24,-27,17,5);ctx.strokeStyle='#d9e3cf';ctx.beginPath();ctx.moveTo(20,-2);ctx.lineTo(17,-30);ctx.lineTo(10,-34);ctx.stroke();ctx.fillStyle='#233431';ctx.beginPath();ctx.arc(0,-9,8,0,Math.PI*2);ctx.fill();ctx.save();if(crashed){ctx.translate(-18,-17);ctx.rotate(performance.now()*.009);}ctx.strokeStyle='#263846';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(-10,-29);ctx.lineTo(-2,-17);ctx.lineTo(9,-13);ctx.stroke();ctx.strokeStyle=front?'#f5e5c4':'#d7f0de';ctx.lineWidth=10;ctx.beginPath();ctx.moveTo(-9,-33);ctx.lineTo(-5,-48);ctx.lineTo(10,-35);ctx.stroke();ctx.fillStyle=color;ctx.beginPath();ctx.arc(-3,-56,8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#183336';ctx.fillRect(0,-59,7,4);ctx.restore();ctx.restore();}
  function draw(dt,now){const size=viewportSize(window),w=size.width,h=size.height,dpr=mxPixelRatio(w,h,window.devicePixelRatio||1)*quality;if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}ctx.setTransform(dpr,0,0,dpr,0,0);const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#9bd3d0');sky.addColorStop(1,'#f9e4b6');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);const predicted=prediction.sample(),rendered=solo?state.players:buffer.sample(now/1000).map(p=>p.id===localId&&predicted?predicted:p),me=rendered.find(p=>p.id===localId),cameraX=me?.x||8,scale=h<450?25:34,base=h*.69,ground=heightAt(cameraX),worldX=x=>(x-cameraX)*scale+w*.32,worldY=(y,lane=0)=>base-(y-ground)*scale-lane;
    for(let layer=0;layer<2;layer++){ctx.fillStyle=layer?'#638d7f':'#8fb39b';ctx.beginPath();ctx.moveTo(0,h);for(let x=0;x<=w+20;x+=20)ctx.lineTo(x,h*(.43+layer*.1)+Math.sin(x*.006+cameraX*.004*(layer+1))*h*.12);ctx.lineTo(w,h);ctx.closePath();ctx.fill();}
    const line=new Path2D();for(let px=-20;px<=w+20;px+=8){const x=cameraX+(px-w*.32)/scale,y=worldY(heightAt(x));if(px===-20)line.moveTo(px,y);else line.lineTo(px,y);}const fill=new Path2D(line);fill.lineTo(w+20,h+250);fill.lineTo(-20,h+250);fill.closePath();
    function track(lane,back){ctx.save();ctx.translate(0,-lane);ctx.fillStyle=back?'#bc9e69':'#986640';ctx.strokeStyle=back?'#9a9d58':'#e1b76a';ctx.lineWidth=back?5:8;ctx.fill(fill);ctx.stroke(line);ctx.restore();}
    const riders=renderLanes(rendered,localId),spacing=h<450?28:38;for(const p of riders){track(p.lane*spacing,!p.front);drawRider(p,p.lane*spacing);}if(!riders.length)track(0,false);
    function drawRider(p,lane){const x=worldX(p.x),y=worldY(p.y-.4,lane);bike(x,y,p.angle,colors[p.color%colors.length],p.front,p.crashTime>0);ctx.fillStyle=p.front?'#173b34':'#355c54';ctx.textAlign='center';ctx.font='700 11px Arial';ctx.fillText(p.name+(p.front?' · DU':' · HINTEN'),x,y-78);}
    const finish=worldX(MX_LENGTH);if(finish>-20&&finish<w+20){ctx.fillStyle='#f4ead1';ctx.fillRect(finish,worldY(terrainHeight(MX_LENGTH))-125,5,125);ctx.fillStyle='#193b35';ctx.fillRect(finish+5,worldY(terrainHeight(MX_LENGTH))-125,64,28);ctx.fillStyle='#fff1cb';ctx.font='bold 14px Arial';ctx.fillText('ZIEL',finish+35,worldY(terrainHeight(MX_LENGTH))-106);}
    for(const event of state?.events||[])if(event.type==='shot'&&state.time-event.time<.16){ctx.strokeStyle='#ffe7a0';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(worldX(event.x),worldY(event.y+1));ctx.lineTo(worldX(event.targetX),worldY(event.targetY+1));ctx.stroke();}
    if(now-hudAt>=100){hudAt=now;label('mx-clock',format(state?.time||0));label('mx-countdown',state?.phase==='countdown'?Math.ceil(state.countdown):'');$('mx-caption').classList.toggle('hidden',now>captionUntil);if(me){canvas.dataset.localX=me.x.toFixed(3);const ordered=[...state.players].sort((a,b)=>a.finished&&b.finished?(a.finishTime??Infinity)-(b.finishTime??Infinity):Number(b.finished)-Number(a.finished)||b.x-a.x);label('mx-position',(ordered.findIndex(p=>p.id===localId)+1)+' / '+state.players.length+' · '+Math.round(me.x)+' / '+MX_LENGTH+' m');}else label('mx-position','');}
  }
  function frame(now){if(!active)return;if(mode==='3d'){requestAnimationFrame(frame);return;}const elapsed=(now-lastTime)/1000,dt=Math.min(.1,elapsed||.016);lastTime=now;if(!document.hidden){if(solo)stepSolo(dt);else if(state?.phase==='running')prediction.step(dt,controls());const started=performance.now();draw(dt,now);drawTotal+=performance.now()-started;frameCount++;frameTimes.push(elapsed*1000);if(now-metricAt>=1000){const duration=(now-metricAt)/1000,fps=frameCount/duration,renderMs=drawTotal/frameCount,p95=[...frameTimes].sort((a,b)=>a-b)[Math.floor(frameTimes.length*.95)]||0;canvas.dataset.fps=fps.toFixed(1);canvas.dataset.ping=Math.round(ping);canvas.dataset.netHz=(packetCount/duration).toFixed(1);canvas.dataset.renderMs=renderMs.toFixed(2);canvas.dataset.frameP95=p95.toFixed(1);label('mx-network',Math.round(fps)+' FPS · Ping '+(ping?Math.round(ping)+' ms':'—')+(packetCount===0&&state?' · Verbindung stockt':''));if(renderMs>18&&quality>.65)quality=Math.max(.65,quality-.1);metricAt=now;frameCount=packetCount=0;drawTotal=0;frameTimes=[];}}requestAnimationFrame(frame);}
  return {open,close,release,showLobby,send3d:value=>{if(mode==='3d')send(value);},ping:()=>ping,isActive:()=>active,isRunning:()=>active&&state?.phase==='running',speed:()=>state?.players.find(p=>p.id===localId)?.vx||0,throttle:()=>keys.has('KeyW')||touch.gas||touch.boost,boosting:()=>keys.has('Space')||keys.has('ShiftLeft')||touch.boost};
